// Compare observable descriptor changes with the ETag generated by the server.
const { MODEL: M, FIXTURE, ROLES } = require('../load-model.js')(process.argv[2]);
const need = (accessClass, operation, extra = {}) => ({ accessClass, operation, ...extra });
const a = ['companies', 'A'], b = [...a, 'teams', 'B'], w = [...b, 'widgets', 'w1'];
// Give Search a second valid resource-level READ filter.
const F = { ...FIXTURE, methods: [...FIXTURE.methods, { name: 'PeekWidget', authz: { requirements: [need('READ', 'peek')] }, request: { name: { type: 'Widget' } } }] };
const widget = F.resources.Widget;
const resource = (patch) => ({ ...F, resources: { ...F.resources, Widget: { ...widget, ...patch } } });
const method = (name, edit) => ({ ...F, methods: F.methods.map((m) => m.name === name ? edit(m) : m) });
const requirements = (name, request) => (J) => M.requirementsFor(J, name, request).map((r) => [r.key, r.cls, r.targets, r.unbound, r.wildcard]);
const keys = (role) => (J) => M.keysFor({ scope: a, selectors: ROLES[role] }, J.keys).sort();
const cases = [
  ['guarded owner becomes output-only', resource({ fields: { ...widget.fields, owner: { outputOnly: true } } }), requirements('UpdateWidget', { 'widget.name': w, update: { mask: ['owner'], populated: ['owner'] } })],
  ['batch request declares a hoisted allow_missing', method('BatchUpdateWidgets', (m) => ({ ...m, request: { ...m.request, allow_missing: true } })), requirements('BatchUpdateWidgets', { 'requests[].widget.name': [w], allow_missing: true })],
  ['Widget pattern variables renamed (company <-> team)', resource({ patterns: ['companies/{team}/teams/{company}/widgets/{widget}'] }), requirements('ListWidgets', { parent: [...a, 'teams', '-'] })],
  ['CountWidgets reclassified READ -> ADMIN', method('CountWidgets', (m) => ({ ...m, authz: { requirements: [need('ADMIN', 'count')] } })), keys('viewer')],
  ['MoveWidget drops its delete requirement', method('MoveWidget', (m) => ({ ...m, authz: { requirements: [need('CREATE', 'create', { targetField: 'destination_parent' })] } })), requirements('MoveWidget', { name: w, destination_parent: b })],
  ['ExpungeWidget no longer explicit-grant-only', method('ExpungeWidget', (m) => ({ ...m, authz: { requirements: [need('DELETE', 'expunge')] } })), keys('admin')],
  ['Widget gains a second parent pattern', resource({ patterns: [...widget.patterns, 'companies/{company}/widgets/{widget}'] }), requirements('GetWidget', { name: [...a, 'widgets', 'w1'] })],
  ['owner guard class ADMIN -> UPDATE', resource({ fields: { ...widget.fields, owner: { guard: need('UPDATE', 'setOwner') } } }), requirements('CreateWidget', { parent: b, populated: ['owner'] })],
  ['SearchWidgets item filter changes', method('SearchWidgets', (m) => ({ ...m, authz: { ...m.authz, itemFilter: 'peek' } })), (J) => J.methods.SearchWidgets.itemFilter],
];

const interpret = (desc) => {
  const model = M.interpret(desc, { fieldGuards: true });
  if (model.errors.length) throw Error(model.errors.join('\n'));
  return model;
};
const base = interpret(F), etag = M.descriptorEtag(base);
for (const [label, desc, observe] of cases) {
  const changed = interpret(desc);
  const behaviourChanges = JSON.stringify(observe(changed)) !== JSON.stringify(observe(base));
  const etagChanges = M.descriptorEtag(changed) !== etag;
  console.log(label.padEnd(50), 'behaviour changes', behaviourChanges, ' ETag changes', etagChanges);
  if (!behaviourChanges || !etagChanges) process.exitCode = 1;
}
